def prepare(points):
    """Prepare a list of (x, y) samples.

    * Accepts an iterable of 2‑tuples ``(x, y)``.
    * Raises ``ValueError`` if the input is empty or contains duplicate x
      values.
    * Returns a list sorted by the x coordinate.
    """
    if not points:
        raise ValueError("empty samples")
    seen = {}
    for x, y in points:
        if x in seen:
            raise ValueError("duplicate coordinate")
        seen[x] = y
    # ``sorted`` returns a list of tuples sorted by the first element.
    return sorted(seen.items())

