def estimate(points, x):
    """Piecewise linear interpolation.

    * ``points`` must be a list of (x, y) sorted by x.
    * Values outside the support are clamped to the nearest endpoint.
    * Handles a single sample gracefully.
    """
    # Clamp to the nearest endpoint when outside the domain
    if x <= points[0][0]:
        return points[0][1]
    if x >= points[-1][0]:
        return points[-1][1]
    # Find the segment containing x
    for i in range(1, len(points)):
        left, right = points[i - 1], points[i]
        if x <= right[0]:
            # Linear interpolation preserving sign of slope
            return left[1] + (right[1] - left[1]) * (x - left[0]) / (right[0] - left[0])
    # Fallback (should not be reached)
    return points[-1][1]

