files.operators.py:
def apply(op, left, right):
    """Apply an operator to two integer operands.

    Supported operators are ``+``, ``-``, ``*`` and ``/``.
    Division truncates toward zero, matching Python's ``int`` division
    semantics for negative numbers (i.e., ``int(left / right)``).
    Raises ``ValueError`` for division by zero or unknown operators.
    """
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        if right == 0:
            raise ValueError("division by zero")
        # Truncate toward zero using // on absolute values and sign handling
        quotient = abs(left) // abs(right)
        return -quotient if (left < 0) != (right < 0) else quotient
    raise ValueError("unsupported operator")

