    # If there is only one sample, return its y for any x
    if len(points) == 1:
        return points[0][1]
    # Clamp to endpoints
    if x <= points[0][0]:
        return points[0][1]
    if x >= points[-1][0]:
        return points[-1][1]
    # Find interval for piecewise linear interpolation
    for i in range(1, len(points)):
        left = points[i - 1]
        right = points[i]
        if x <= right[0]:
            # Compute slope correctly using the distance between x coordinates
            dx = right[0] - left[0]
            if dx == 0:
                # Should not happen due to duplicate check, but guard anyway
                return left[1]
            dy = right[1] - left[1]
            return left[1] + dy * (x - left[0]) / dx
    # Fallback (should not reach here)
    return points[-1][1]

