    # If total weight is zero, only zero seats are allowed
    if total == 0:
        if seats != 0:
            raise ValueError("zero total")
        return {k: 0 for k in weights}, {k: 0 for k in weights}

    # Hamilton's method: initial allocation is the floor of the exact proportion
    base = {k: (seats * v) // total for k, v in weights.items()}
