def distribute(base, remainders, seats):
    # seats is the total number of seats to allocate
    allocated = sum(base.values())
    remaining = seats - allocated
    # No seats left to distribute
    if remaining <= 0:
        return {k: base[k] for k in sorted(base)}

    # Order by descending remainder, then ascending name for ties
    priority = sorted(base.keys(), key=lambda k: (-remainders[k], k))
    result = dict(base)
    for name in priority[:remaining]:
        result[name] += 1
    # Return a dict sorted by name for deterministic output
    return {k: result[k] for k in sorted(result)}

