def distribute(base, remainders, seats):
    # Copy the base allocation
    result = dict(base)
    # How many seats are still to distribute?
    remaining = seats - sum(base.values())
    if remaining <= 0:
        # Nothing left to allocate; just return a name‑sorted dict
        return {k: result[k] for k in sorted(result)}

    # Sort names by descending remainder, then ascending name for ties
    priority = sorted(base.keys(), key=lambda k: (-remainders[k], k))
    # Give one extra seat to the top 'remaining' names
    for name in priority[:remaining]:
        result[name] += 1
    # Return a dict sorted by name for deterministic output
    return {k: result[k] for k in sorted(result)}

