def index_rows(rows):
    """Create an index mapping keys to a list of row values.

    Rows with a ``key`` of ``None`` are ignored because null keys never match.
    The function does not modify the input rows.
    """
    index = {}
    for row in rows:
        key = row.get("key")
        if key is not None:
            # Preserve the order of appearance for each key
            index.setdefault(key, []).append(row["value"])
    return index

