def estimate(points, x):
    """Return the piecewise linear interpolation of *points* at *x*.

    *points* must be a list of (x, y) tuples sorted by x.  The function
    clamps *x* to the nearest endpoint if it lies outside the support.
    """
    if not points:
        raise ValueError("no points provided")
    # Single point: return its y for any query
    if len(points) == 1:
        return points[0][1]
    # Clamp to endpoints
    if x <= points[0][0]:
        return points[0][1]
    if x >= points[-1][0]:
        return points[-1][1]
    # Find the interval containing x
    for i in range(1, len(points)):
        left, right = points[i - 1], points[i]
        if x <= right[0]:
            # Linear interpolation
            t = (x - left[0]) / (right[0] - left[0])
            return left[1] + t * (right[1] - left[1])
    # Should never reach here
    raise RuntimeError("interpolation error")

