    """Perform a stable left equijoin.

    Args:
        left_rows (list): List of dicts with "key" and "value".
        right_index (dict): Mapping from key to list of right values.

    Returns:
        list: List of result rows each containing "key", "left", and "right".
    """
    result = []
    for left in left_rows:
        key = left.get("key")
        left_val = left["value"]
        # Null keys never match any right rows.
        matches = right_index.get(key, []) if key is not None else []
        if matches:
