def distance(a, b):
    """Return the unit‑cost Levenshtein distance between *a* and *b*.

    The implementation uses the classic dynamic‑programming algorithm with
    O(min(len(a), len(b))) space.  Substitutions, insertions and deletions
    each cost 1; matching characters cost 0.
    """
    # Ensure inputs are strings – other types are considered mismatched.
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("both arguments must be strings")

    # Quick shortcuts for empty strings.
    if a == b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)

    # Ensure the shorter string is used for the inner loop to minimise memory.
    if len(a) > len(b):
        a, b = b, a

    previous = list(range(len(b) + 1))
    for i, left_char in enumerate(a, 1):
        current = [i]
        for j, right_char in enumerate(b, 1):
            cost = 0 if left_char == right_char else 1
            current.append(
                min(
                    current[-1] + 1,          # insertion
                    previous[j] + 1,          # deletion
                    previous[j - 1] + cost    # substitution
                )
            )
        previous = current
    return previous[-1]

