def quotas(weights, seats):
    # Validate inputs
    if not isinstance(seats, int) or seats < 0:
        raise ValueError("invalid allocation")
    if not isinstance(weights, dict) or not weights:
        raise ValueError("invalid allocation")
    for name, v in weights.items():
        if not isinstance(v, int) or v < 0:
            raise ValueError("invalid allocation")
    total = sum(weights.values())
    if total == 0:
        if seats != 0:
            raise ValueError("zero total")
        # All allocations zero
        return {k: 0 for k in weights}, {k: 0 for k in weights}
    # Compute base allocation and remainders using integer arithmetic
    base = {k: seats * v // total for k, v in weights.items()}
    remainders = {k: seats * v % total for k, v in weights.items()}
    return base, remainders

files.remainders.py:
def distribute(base, remainders, seats):
    # base: dict of current allocations
    # remainders: dict of remainders for each name
    # seats: total seats to allocate
    result = dict(base)
    allocated = sum(result.values())
    remaining = seats - allocated
    if remaining <= 0:
        return {k: result[k] for k in sorted(result)}
    # Sort names by descending remainder, then ascending name
    sorted_names = sorted(base.keys(), key=lambda k: (-remainders[k], k))
    for name in sorted_names:
        if remaining == 0:
            break
        result[name] += 1
        remaining -= 1
    return {k: result[k] for k in sorted(result)}

