def index_rows(rows):
    """Create an index mapping each non-null key to a list of its values.

    The order of values for a given key follows the order they appear in ``rows``.
    Null keys are ignored because they never match according to the contract.
    """
    index = {}
    for row in rows:
        key = row.get("key")
        if key is None:
            continue
        # Append the value to the list for this key, preserving order.
        index.setdefault(key, []).append(row["value"])
    return index

