def index_rows(rows):
    """Build an index mapping non-null keys to a list of their values.

    Args:
        rows (list of dict): Each dict has at least a "key" and "value" entry.

    Returns:
        dict: Mapping from key to list of values. Null keys are omitted.
    """
    index = {}
    for row in rows:
        key = row.get("key")
        if key is not None:
            index.setdefault(key, []).append(row["value"])
    return index

