files.quotas.py:
def quotas(weights, seats):
    # Validate inputs
    if type(seats) is not int or seats < 0:
        raise ValueError("invalid allocation")
    if not isinstance(weights, dict):
        raise ValueError("invalid allocation")
    for name, v in weights.items():
        if type(v) is not int or v < 0:
            raise ValueError("invalid allocation")
    total = sum(weights.values())
    # Handle zero total
    if total == 0:
        if seats:
            raise ValueError("zero total")
        return {k: 0 for k in weights}, {k: 0 for k in weights}
    # Compute base allocation (floor) and remainders
    base = {}
    remainders = {}
    for name, v in weights.items():
        # floor of seats * v / total
        base[name] = (seats * v) // total
        # remainder as integer difference
        remainders[name] = seats * v - base[name] * total
    return base, remainders

files.remainders.py:
def distribute(base, remainders, seats):
    # Calculate how many seats are left to distribute
    distributed = sum(base.values())
    remaining = seats - distributed
    if remaining < 0:
        raise ValueError("seats less than base allocation")
    # Sort names by descending remainder, then ascending name
    sorted_names = sorted(base.keys(), key=lambda n: (-remainders[n], n))
    result = dict(base)
    for name in sorted_names[:remaining]:
        result[name] += 1
    return {k: result[k] for k in sorted(result)}

